def split_overhead_fraction(p, hw, cfg) -> float:
    """Per-split fixed cost (pipeline fill/drain + serial fix-up) relative to the K iterations one split runs. Larger is worse."""
    iters = max(1, math.ceil(p.K / max(1, cfg.tile_k * max(1, cfg.split_k))))
    return min(4.0, (cfg.stages + 1.0) / iters)
